import{_ as t,a as n}from"./chunks/ugso_trigger_value.B1HIiOLA.js";import{_ as r,o as i,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const o="/assets/blocks-for-ha/schedule-de.png",l="/assets/blocks-for-ha/schedule-dark-de.png",f=JSON.parse('{"title":"Datum und Zeit","description":"Zeit-Blocks, HA-Zeitzone und Gegenüberstellung mit ioBroker.","frontmatter":{"title":"Datum und Zeit","description":"Zeit-Blocks, HA-Zeitzone und Gegenüberstellung mit ioBroker."},"headers":[],"relativePath":"projects/blocks-for-ha/time.md","filePath":"projects/blocks-for-ha/time.md","lastUpdated":1792754903000}'),d={name:"projects/blocks-for-ha/time.md"};function h(u,e,g,c,k,m){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="datum-und-zeit" tabindex="-1">Datum und Zeit <a class="header-anchor" href="#datum-und-zeit" aria-label="Permalink to &quot;Datum und Zeit&quot;">​</a></h1><h2 id="zeitplan-und-ausloser-seit-0-1-60" tabindex="-1">Zeitplan und Auslöser seit 0.1.60 <a class="header-anchor" href="#zeitplan-und-ausloser-seit-0-1-60" aria-label="Permalink to &quot;Zeitplan und Auslöser seit 0.1.60&quot;">​</a></h2><p>Unter <strong>Auslöser → Zeitplan</strong> die CRON-Regel anklicken. Der Dialog bietet <strong>Wizard / Einfach / CRON</strong>, entsprechend den ioBroker-Popups. Einfach erzeugt Intervalle; der Wizard zusätzlich eine feste Uhrzeit mit numerischen Wochentagen. CRON hat Feldreiter und optional Sekunden. <strong>OK</strong> übernimmt eine gültige Regel; <strong>Abbrechen</strong> und Escape bewahren den bisherigen Wert. Die Darstellung folgt Hell/Dunkel. Alle Dialogtexte sind in DE/EN/FR verfügbar.</p><p><img src="'+t+'" alt="Zeitplan"></p><p><img src="'+o+'" alt="CRON-Dialog"></p><p><img src="'+l+'" alt="CRON-Dialog dunkel"></p><p>Fünf Felder: Minute, Stunde, Monatstag, Monat, Wochentag. Sechs Felder beginnen mit Sekunden. Zahlen, Listen, Bereiche und Schritte sind möglich. Beispiele: <code>*/5 * * * *</code> alle fünf Minuten; <code>*/30 * * * * *</code> alle 30 Sekunden; <code>30 7 * * 1-5</code> werktags um 07:30. Sonntag ist 0 oder 7. Home Assistant führt die Automation in seiner Ortszeit aus; kein Browser-Timer. <code>/Schritte</code> beziehen sich auf das jeweilige Uhrzeitfeld: <code>*/7</code> Minuten beginnt in jeder Stunde wieder bei Minute 0.</p><p>Die Ausgabe verwendet native <code>time_pattern</code> oder <code>time</code>-Auslöser mit <code>weekday</code>. Monat und Monatstag müssen <code>*</code> sein. Datum, Gültigkeitsbereich, einmalige Termine und astronomische Tages-/Nachtfenster sind im Dialog noch nicht umgesetzt. Diese Regeln werden nicht stillschweigend ignoriert. Wochentagsregeln werden höchstens in 2000 einzelne Uhrzeiten aufgelöst; häufigere Regeln sind ausdrücklich abgewiesen. Kalender-Auslöser und HA-Bedingungen bleiben separat verfügbar. Projekt-JSON erhält die CRON-Regel, YAML die gleichwertige native HA-Struktur.</p><table tabindex="0"><thead><tr><th>ioBroker-Auslöser</th><th>Blocks for HA / HA-Umsetzung</th></tr></thead><tbody><tr><td>Falls Objekt / Falls Objekte</td><td>Zustandsauslöser mit einer oder mehreren Entitäten; von/nach, Attribut und Haltezeit. Keine ioBroker-Objekt-IDs.</td></tr><tr><td>Auslösung durch / ack bestätigen</td><td>HA besitzt hier kein ioBroker-<code>ack</code>. Kein künstlicher Bestätigungsblock.</td></tr><tr><td>↪ Wert / Meldung</td><td>Neuer Auslöserdatenblock: Wert, alter Wert, Entitäts-ID, Auslöser-ID/-typ, MQTT-Meldung/JSON und Ereignisdaten. Fehlende Daten ergeben <code>none</code>; Zahlen bei Bedarf umwandeln.</td></tr><tr><td>Astro mit Versatz</td><td>Sonnenauf-/untergang mit optionalem Minutenversatz. Weitere Sonnenbedingungen über native HA-Blöcke.</td></tr><tr><td>Zeitplan / CRON</td><td>Dialog wie oben, native HA-Ausführung. Keine dynamische Registrierung benannter ioBroker-Zeitpläne.</td></tr><tr><td>Nachricht empfangen</td><td>MQTT- oder HA-Ereignisauslöser mit Filter; kein direkter Empfang von ioBroker-Skriptnachrichten.</td></tr><tr><td>Log-Nachricht</td><td>HA-Ereignisauslöser mit <code>system_log_event</code>, sofern HA diese Ereignisse entsprechend bereitstellt. Kein eigenständiger ioBroker-Loglistener.</td></tr><tr><td>Datei-/Enum-Ereignisse</td><td>Keine direkte Umsetzung. Vorhandene HA-Integration bzw. deren Ereignisse/Entitäten verwenden.</td></tr><tr><td>Weitere native HA-Auslöser</td><td>MQTT, Template, Webhook, Gerät, Tag, Gespräch, Zone und Geolocation stehen jetzt direkt unter <strong>Auslöser</strong>, ohne Doppelung unter HA erweitert.</td></tr></tbody></table><p><img src="'+n+'" alt="Auslöserdaten"></p><p>Referenzen: <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_trigger.ts" target="_blank" rel="noreferrer">Originale ioBroker-Triggerblöcke</a>, <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">native HA-Auslöser</a>. Die Oberfläche orientiert sich am Original; Ausführung und Daten bleiben HA-spezifisch.</p><p>Seit <strong>0.1.11</strong> enthält die Kategorie sieben zusätzliche Blocks. <a href="./blocks#datum-und-zeit-seit-0-1-11">Alle Blocks mit Bildern</a>. Die Oberfläche verwendet die originale Blockly-Library; die Übersetzung nach HA-Jinja ist eine eigene UGSo-Implementierung. Referenz sind die <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_time.ts" target="_blank" rel="noreferrer">Zeit-Blocks des ioBroker-JavaScript-Adapters</a> und die <a href="https://docs.blockly.com/guides/create-custom-blocks/define/block-definitions/" target="_blank" rel="noreferrer">Blockly-Blockdefinitionen</a>.</p><h2 id="iobroker-ugso-blocks-fur-ha" tabindex="-1">ioBroker / UGSo Blocks für HA <a class="header-anchor" href="#iobroker-ugso-blocks-fur-ha" aria-label="Permalink to &quot;ioBroker / UGSo Blocks für HA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ioBroker</th><th>Unser Block / Umsetzung</th></tr></thead><tbody><tr><td>Aktuelle Zeit ist …, feste Uhrzeit</td><td><strong>Uhrzeitvergleich</strong> mit kleiner, kleiner/gleich, größer, größer/gleich, gleich, zwischen und nicht zwischen. Das Endfeld erscheint bei Zeiträumen.</td></tr><tr><td>Aktuelle Zeit mit Checkbox und andockbarem Wert</td><td><strong>Uhrzeitvergleich mit Eingängen</strong>: Text-Blocks für Start/Ende. Haken aus: zusätzlicher Datumswert-Anschluss für die zu vergleichende Zeit.</td></tr><tr><td>Aktuelle Zeit als Datum-Objekt oder formatierter Wert</td><td><strong>Aktuelle Zeit als Datumswert</strong> und separater <strong>Formatierungsblock</strong>. Diese Trennung verhindert, dass formatierte Texte versehentlich als Datumswerte verrechnet werden.</td></tr><tr><td>Berechnete Zeit</td><td><strong>Kalenderbeginn</strong>: Tag, nächster Tag, Woche (Montag), Monat und Jahr. Weitere ioBroker-Kalendergrenzen sind noch nicht vorhanden.</td></tr><tr><td>Aktuelle Zeit von Astroereignis plus Offset</td><td><strong>Nächste Sonnenzeit</strong>: Aufgang, Untergang, Morgen-/Abenddämmerung, Höchststand und Sonnenmitternacht, mit positivem/negativem Minutenoffset.</td></tr><tr><td>Zeit berechnen, Basis ± Zahl, Einheit</td><td><strong>Zeit berechnen</strong>: Datumswert ± Zahl; Millisekunden, Sekunden, Minuten, Stunden oder Tage.</td></tr></tbody></table><h2 id="anschlusse-und-bedienung" tabindex="-1">Anschlüsse und Bedienung <a class="header-anchor" href="#anschlusse-und-bedienung" aria-label="Permalink to &quot;Anschlüsse und Bedienung&quot;">​</a></h2><p>Zeitvergleiche liefern <strong>Boolean</strong> und passen in Bedingungen, UND/ODER/NICHT oder Falls. Datumswerte besitzen einen <strong>Time-Anschluss</strong>: Aktuelle Zeit, Kalenderbeginn, Sonnenzeit und Zeitberechnung lassen sich untereinander verschachteln. Zahlen gehören in Offset/Betrag; formatierte Uhrzeiten als Text in die andockbaren Vergleichsgrenzen. Formatierung bietet HH:mm, HH:mm:ss, ISO-Datum, deutsches Datum, Datum/Uhrzeit, ISO mit Zeitzone und Unix-Sekunden.</p><p>Beispiel: <strong>Aktuelle Zeit → Zeit berechnen (+ 30 Minuten) → Zeit formatieren (HH:mm)</strong>, anschließend als Variable setzen. Das erzeugte Template lautet:</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ (</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">now</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timedelta</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">minutes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">30)).</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">strftime</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%H:%M&quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Zwischen 22:00 und 06:00</strong> schließt die Nacht über Mitternacht ein. Der Start gehört dazu, das Ende nicht. Gleiche Grenzen bedeuten einen leeren Zeitraum; „nicht zwischen“ ist dessen Gegenteil. Feste Uhrzeiten müssen HH:mm oder HH:mm:ss sein. Dynamische Textgrenzen müssen zur Laufzeit dasselbe Format liefern; ungültige Werte erzeugen einen HA-Template-Fehler. Der Vergleich arbeitet auf Sekunden; „gleich 12:00“ bedeutet 12:00:00 und ist kein zuverlässiger Zeit-Auslöser.</p><h2 id="ausfuhrung-und-grenzen" tabindex="-1">Ausführung und Grenzen <a class="header-anchor" href="#ausfuhrung-und-grenzen" aria-label="Permalink to &quot;Ausführung und Grenzen&quot;">​</a></h2><p>Die erzeugten Templates werden <strong>in Home Assistant</strong> ausgewertet. Der Browser baut das YAML und führt keine eigene laufende Zeitsteuerung aus. Die Funktionen verwenden die konfigurierte HA-Zeitzone: <a href="https://www.home-assistant.io/template-functions/#date-time" target="_blank" rel="noreferrer">HA-Datums-/Zeitfunktionen</a>. Kalenderbeginn nutzt lokale Mitternacht; Tage folgen der lokalen Kalenderrechnung, auch bei Sommerzeitwechsel. Eine Rechnung „+ 24 Stunden“ garantiert bei einem Zeitwechsel keine 24 real verstrichenen UTC-Stunden.</p><p>Sonnenwerte kommen aus den Attributen der <a href="https://www.home-assistant.io/integrations/sun/#sensors" target="_blank" rel="noreferrer">HA-Sun-Integration</a>. Diese liefern das <strong>nächste Ereignis</strong>, nicht stets das Ereignis des heutigen Tages. Die UTC-Angabe wird vor Berechnung/Formatierung in HA-Ortszeit umgewandelt. Fehlende Werte, etwa bei nicht verfügbarer Integration oder einem nicht berechenbaren Ereignis, ergeben einen Template-Fehler; es wird keine Ersatzzeit erfunden.</p><p>Ein Zeitvergleich prüft die Uhrzeit <strong>beim Durchlaufen der Bedingung</strong>. Er startet die Automation nicht und wartet nicht bis zur passenden Uhrzeit. Dafür einen Uhrzeit- oder Sonnen-Auslöser verwenden. Der neue Sonnenwert-Block ersetzt keinen Sonnen-Auslöser.</p><p><strong>Blocks-Projekt (JSON)</strong> erhält Form, Auswahl und dynamische Eingänge. Beim <strong>YAML-Öffnen</strong> bleiben diese Zeittemplates inhaltlich erhalten, erscheinen aber als allgemeine Template-Blocks. Ein zuvor in einer HA-Variable gespeicherter Datumswert kann als Text vorliegen; unser Variablen-Leseblock hat deshalb keinen Time-Anschluss. Datumswerte direkt verschachteln oder seit <strong>0.1.12</strong> den Variablen-Leseblock über <strong>Nach Datum/Zeit</strong> konvertieren. <a href="./conversion">Konvertierung und Einheiten</a>. Konvertierte Laufzeitzahlen können jetzt auch in Betrag und Sonnenoffset andocken.</p><p>Prüfung: Blockly-/YAML-Rundläufe, typisierte Anschlüsse, dynamische Felder sowie Jinja-Prüfungen für Nachtgrenzen und Sommerzeit. Eine Ausführung auf einem echten HA-System ist noch nicht verifiziert.</p>',25)])])}const A=r(d,[["render",h]]);export{f as __pageData,A as default};
